style.css:
@-moz-document domain("roblox.com") {
/* Fundo principal do site com a imagem que você enviou */
  body, .content-wrapper, .footer {
    background-image: url('https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTKRqZTRGKv1uF0n_w2eRkjiaSalkdep8bpFE5DyiKHRuyEWpBUNy9G2jUd&s=10') !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
  }

  /* Cabeçalho superior (Azul do traje) */
  .navbar-default, .notification-stream-base {
    background-color: #1e6bbb !important;
  }

  /* Botões e elementos clicáveis (Preto/Cinza escuro para combinar) */
  .btn-secondary-md, .btn-primary-md {
    background-color: #15161a !important;
    color: #1e6bbb !important;
    border: 1px solid #1e6bbb !important;
  }
  
  /* Cor de fundo dos blocos de jogos e menus para não sumirem */
  .section-content, .container-main, .menu-sidebar {
    background-color: rgba(21, 22, 26, 0.85) !important;
  }

  /* Garante que todos os textos fiquem brancos e fáceis de ler */
  h1, h2, h3, h4, span, p, a {
    color: #ffffff !important;
  }
}
